/* 
 * 		true / false
 */
public class 선택조건문_1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a = 11;
		
		if (a % 2 ==0) {
			// true
			System.out.println(a + "은 짝수다");
		} else {
			// false
			System.out.println(a + "은 홀수다");
		}

	}

}
